91	int32_t ChooseBlockM(int32_t mOut)
92	{
93	    for (int32_t candidate : {64, 32, 16, 8, 4, 2}) {
94	        if (candidate <= mOut && mOut % candidate == 0) {
95	            return candidate;
96	        }
97	    }
98	    TORCH_CHECK(false, "Unsupported output spatial size: M_out=", mOut);
99	}
100	
101	int32_t ChooseBlockC(int32_t c)
102	{
103	    for (int32_t candidate : {256, 128, 64, 32}) {
104	        if (candidate <= c && c % candidate == 0) {
105	            return candidate;
106	        }
107	    }
108	    return 0;
109	}
110	
111	int32_t ResolveImplMode(int32_t splitMode, int32_t kH, int32_t kW, int32_t sH, int32_t sW,
112	                        int32_t pH, int32_t pW, int32_t c)
113	{
114	    if (kH == 1 && kW == 1 && sH == 1 && sW == 1 && pH == 0 && pW == 0) {
115	        return IMPL_REDUCE_D;
116	    }
117	    if (splitMode == SPLIT_MODE_C) {
118	        int32_t blockC = ChooseBlockC(c);
119	        if (blockC > 0) {
120	            return IMPL_SPLIT_C;
121	        }
122	        TORCH_CHECK(false, "split_c scenario requires divisible channel tiles, got C=", c);
123	    }
124	    if (splitMode == SPLIT_MODE_W) {
125	        return IMPL_SPLIT_W;
126	    }
127	    if (splitMode == SPLIT_MODE_MULTI_W) {
128	        return IMPL_MULTI_W;
129	    }
130	    return IMPL_GENERIC;
131	}
