#ifndef KERNEL_COMMON_H
#define KERNEL_COMMON_H

#include "kernel_operator.h"

template <typename Tiling>
__aicore__ inline void CopyTiling(Tiling *dst, GM_ADDR srcGM)
{
    auto tilingBuf = AscendC::TBuf<>();
    AscendC::TPipe *setupPipe = AscendC::GetTPipe();
    setupPipe->InitBuffer(tilingBuf, sizeof(Tiling));
    auto local = tilingBuf.template Get<uint8_t>();
    AscendC::DataCopy(local, reinterpret_cast<__gm__ uint8_t *>(srcGM), sizeof(Tiling));
    setupPipe->ValuePipeBarrier(local);
    *dst = *reinterpret_cast<Tiling *>(local.Get());
    setupPipe->DestroyBuffer(tilingBuf);
}

template <typename T>
__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0) {
        return 0;
    }
    return (a + b - 1) / b;
}

#endif
