36	// Shared across all AvgPool3D kernel variants (split_c, split_w, reduce_d,
37	// generic, multi_w). Computes the effective pooling divisor for the given
38	// output position, accounting for padding and countIncludePad/divisorOverride.
39	__aicore__ inline int ComputeDivisorHelper(int od, int oh, int ow,
40	                                            const AvgPool3DKernelTiling &tiling)
41	{
42	    if (tiling.divisorOverride > 0) {
43	        return tiling.divisorOverride;
44	    }
45	    if (tiling.countIncludePad > 0) {
46	        return tiling.kD * tiling.kH * tiling.kW;
47	    }
48	
49	    const int dStart = od * tiling.sD - tiling.pD;
50	    const int hStart = oh * tiling.sH - tiling.pH;
51	    const int wStart = ow * tiling.sW - tiling.pW;
52	
53	    const int dBegin = dStart < 0 ? 0 : dStart;
54	    const int hBegin = hStart < 0 ? 0 : hStart;
55	    const int wBegin = wStart < 0 ? 0 : wStart;
56	
57	    int dEnd = dStart + tiling.kD;
58	    int hEnd = hStart + tiling.kH;
59	    int wEnd = wStart + tiling.kW;
60	
61	    if (dEnd > tiling.D) { dEnd = tiling.D; }
62	    if (hEnd > tiling.H) { hEnd = tiling.H; }
63	    if (wEnd > tiling.W) { wEnd = tiling.W; }
64	
65	    const int validD = dEnd > dBegin ? (dEnd - dBegin) : 0;
66	    const int validH = hEnd > hBegin ? (hEnd - hBegin) : 0;
67	    const int validW = wEnd > wBegin ? (wEnd - wBegin) : 0;
68	    return validD * validH * validW;
69	}
