75	{
76	    if ASCEND_IS_AIV {
77	        const int workerId = static_cast<int>(AscendC::GetBlockIdx());
78	        int workerCount = launchBlocks;
79	        if (workerCount <= 0) {
80	            workerCount = 1;
81	        }
82	        const int totalRows = N * outSpatial;
83	        for (int outRow = workerId; outRow < totalRows; outRow += workerCount) {
84	            processRowFn(outRow);
85	        }
86	    }
87	}
