#pragma once

#ifndef K_MAX_SHAPE_DIM
#define K_MAX_SHAPE_DIM 0
#endif

#include "kernel_operator.h"
#include "kernel_common.h"
#include "max_pool3d_tiling.h"

template <typename T>
class MaxPool3dKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe)
    {
        CopyTiling(&tiling_, tilingGM);

        uint64_t xTotal = static_cast<uint64_t>(tiling_.N) * tiling_.inSpatial * tiling_.C;
        uint64_t yTotal = static_cast<uint64_t>(tiling_.N) * tiling_.outSpatial * tiling_.C;
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), xTotal);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), yTotal);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            int rawLen = tiling_.vectorLen;
            if (rawLen <= 0) { rawLen = 256; }
            if (rawLen > tiling_.C) { rawLen = tiling_.C; }
            vecLen_ = rawLen;

            pipe_->InitBuffer(inQueue_, 1, static_cast<uint32_t>(vecLen_ * sizeof(T)));
            pipe_->InitBuffer(outQueue_, 1, static_cast<uint32_t>(vecLen_ * sizeof(T)));

            if constexpr (std::is_same_v<T, float>) {
                pipe_->InitBuffer(accBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
            } else {
                // FP16/BF16: need extra buffer for fp32 accumulation + cast
                pipe_->InitBuffer(accBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
                pipe_->InitBuffer(castBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int workerId = static_cast<int>(AscendC::GetBlockIdx());
            int workerCount = tiling_.launchBlocks;
            if (workerCount <= 0) {
                workerCount = 1;
            }
            const int totalRows = tiling_.totalRows;
            for (int outRow = workerId; outRow < totalRows; outRow += workerCount) {
                ProcessOneRow(outRow);
            }
        }
    }

    __aicore__ inline void ProcessOneRow(int outRow)
    {
        const int nIdx = outRow / tiling_.outSpatial;
        const int outRem = outRow - nIdx * tiling_.outSpatial;
        const int od = outRem / (tiling_.OH * tiling_.OW);
        const int odRem = outRem - od * (tiling_.OH * tiling_.OW);
        const int oh = odRem / tiling_.OW;
        const int ow = odRem - oh * tiling_.OW;

        for (int cBase = 0; cBase < tiling_.C; cBase += vecLen_) {
            const int remain = tiling_.C - cBase;
            const int cLen = remain < vecLen_ ? remain : vecLen_;
            ProcessOneChunk(nIdx, od, oh, ow, outRow, cBase, cLen);
        }
    }

    __aicore__ inline void ProcessOneChunk(int nIdx, int od, int oh, int ow,
                                            int outRow, int cBase, int cLen)
    {
        if constexpr (std::is_same_v<T, float>) {
            ProcessOneChunkFP32(nIdx, od, oh, ow, outRow, cBase, cLen);
        } else {
            ProcessOneChunkFP16(nIdx, od, oh, ow, outRow, cBase, cLen);
        }
    }

private:
    __aicore__ inline void ProcessOneChunkFP32(int nIdx, int od, int oh, int ow,
                                                int outRow, int cBase, int cLen)
    {
        // Initialize accumulator to -FLT_MAX
        auto accLocal = accBuf_.Get<float>();
        AscendC::Duplicate(accLocal, static_cast<float>(-3.402823466e+38f), cLen);

        // Accumulate max over pooling window
        MaxOverWindow(nIdx, od, oh, ow, cBase, cLen, accLocal);

        // Write output: DeQue from VECOUT → DataCopy to GM
        outQueue_.AllocTensor<float>(outLocal_.template ReinterpretCast<float>());
        auto outFp32 = outLocal_.template ReinterpretCast<float>();
        AscendC::Duplicate(outFp32, accLocal, cLen);
        outQueue_.EnQue(outFp32);
        outQueue_.DeQue<float>(outFp32);
        AscendC::DataCopy(yGM_[static_cast<uint64_t>(outRow) * tiling_.C + cBase],
                          outFp32, cLen);
        outQueue_.FreeTensor(outFp32);
    }

    __aicore__ inline void ProcessOneChunkFP16(int nIdx, int od, int oh, int ow,
                                                int outRow, int cBase, int cLen)
    {
        // Initialize accumulator to -FLT_MAX (fp32)
        auto accLocal = accBuf_.Get<float>();
        AscendC::Duplicate(accLocal, static_cast<float>(-3.402823466e+38f), cLen);

        // Accumulate max over pooling window
        MaxOverWindowFP16Cast(nIdx, od, oh, ow, cBase, cLen, accLocal);

        // Write output: Cast fp32→T, DeQue → DataCopy to GM
        outQueue_.AllocTensor<T>(outLocal_);
        AscendC::Cast(outLocal_, accLocal, AscendC::RoundMode::CAST_ROUND, cLen);
        outQueue_.EnQue(outLocal_);
        outQueue_.DeQue<T>(outLocal_);
        AscendC::DataCopy(yGM_[static_cast<uint64_t>(outRow) * tiling_.C + cBase],
                          outLocal_, cLen);
        outQueue_.FreeTensor(outLocal_);
    }

    // FP32 path: load input directly, no cast needed
    __aicore__ inline void MaxOverWindow(int nIdx, int od, int oh, int ow,
                                          int cBase, int cLen,
                                          AscendC::LocalTensor<float> &accLocal)
    {
        for (int kd = 0; kd < tiling_.kD; ++kd) {
            const int idVal = od * tiling_.sD - tiling_.pD + kd;
            if (idVal < 0 || idVal >= tiling_.D) { continue; }
            for (int kh = 0; kh < tiling_.kH; ++kh) {
                const int ihVal = oh * tiling_.sH - tiling_.pH + kh;
                if (ihVal < 0 || ihVal >= tiling_.H) { continue; }
                for (int kw = 0; kw < tiling_.kW; ++kw) {
                    const int iwVal = ow * tiling_.sW - tiling_.pW + kw;
                    if (iwVal < 0 || iwVal >= tiling_.W) { continue; }
                    const int inRow = nIdx * tiling_.inSpatial
                                    + idVal * tiling_.hw
                                    + ihVal * tiling_.W
                                    + iwVal;
                    AccumulateOne(inRow, cBase, cLen, accLocal);
                }
            }
        }
    }

    // FP16/BF16 path: load input to fp16/bf16 buffer, cast to fp32, then max
    __aicore__ inline void MaxOverWindowFP16Cast(int nIdx, int od, int oh, int ow,
                                                   int cBase, int cLen,
                                                   AscendC::LocalTensor<float> &accLocal)
    {
        auto castFp32 = castBuf_.Get<float>();
        for (int kd = 0; kd < tiling_.kD; ++kd) {
            const int idVal = od * tiling_.sD - tiling_.pD + kd;
            if (idVal < 0 || idVal >= tiling_.D) { continue; }
            for (int kh = 0; kh < tiling_.kH; ++kh) {
                const int ihVal = oh * tiling_.sH - tiling_.pH + kh;
                if (ihVal < 0 || ihVal >= tiling_.H) { continue; }
                for (int kw = 0; kw < tiling_.kW; ++kw) {
                    const int iwVal = ow * tiling_.sW - tiling_.pW + kw;
                    if (iwVal < 0 || iwVal >= tiling_.W) { continue; }
                    const int inRow = nIdx * tiling_.inSpatial
                                    + idVal * tiling_.hw
                                    + ihVal * tiling_.W
                                    + iwVal;
                    // Load input as T, cast to fp32, then max
                    AccumulateOneWithCast(inRow, cBase, cLen, accLocal, castFp32);
                }
            }
        }
    }

    // FP32: load + max (for FP32 input, no cast needed)
    __aicore__ inline void AccumulateOne(int inRow, int cBase, int cLen,
                                          AscendC::LocalTensor<float> &accLocal)
    {
        inQueue_.AllocTensor<float>(inLocal_.template ReinterpretCast<float>());
        auto inFp32 = inLocal_.template ReinterpretCast<float>();
        AscendC::DataCopy(inFp32, xGM_[static_cast<uint64_t>(inRow) * tiling_.C + cBase], cLen);
        inQueue_.EnQue(inFp32);
        inQueue_.DeQue<float>(inFp32);
        AscendC::Max(accLocal, accLocal, inFp32, cLen);
        inQueue_.FreeTensor(inFp32);
    }

    // FP16/BF16: load as T, cast to fp32, then max
    __aicore__ inline void AccumulateOneWithCast(int inRow, int cBase, int cLen,
                                                   AscendC::LocalTensor<float> &accLocal,
                                                   AscendC::LocalTensor<float> &castFp32)
    {
        inQueue_.AllocTensor<T>(inLocal_);
        AscendC::DataCopy(inLocal_, xGM_[static_cast<uint64_t>(inRow) * tiling_.C + cBase], cLen);
        inQueue_.EnQue(inLocal_);
        inQueue_.DeQue<T>(inLocal_);
        AscendC::Cast(castFp32, inLocal_, AscendC::RoundMode::CAST_NONE, cLen);
        AscendC::Max(accLocal, accLocal, castFp32, cLen);
        inQueue_.FreeTensor(inLocal_);
    }

private:
    MaxPool3dKernelTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};
    int vecLen_{0};

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;

    // Input queue (VECIN): GM→UB for input data
    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueue_;
    // Output queue (VECOUT): UB→GM for output data
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueue_;
    // Accumulator buffer (VECCALC): fp32 accumulation
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
    // Cast buffer (VECCALC): only used for FP16/BF16 cast intermediate
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;

    // Reusable local tensors (reallocated each iteration)
    AscendC::LocalTensor<T> inLocal_;
    AscendC::LocalTensor<T> outLocal_;
};
