#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "../op_kernel/max_pool3d_tiling.h"

#include "aclrtlaunch_max_pool3d_float.h"
#include "aclrtlaunch_max_pool3d_half.h"
#include "aclrtlaunch_max_pool3d_bfloat16.h"

namespace ascend_kernel {

namespace {

// ------------------------------------------------------------------
// Helpers
// ------------------------------------------------------------------
int64_t CeilDiv(int64_t value, int64_t factor)
{
    if (factor == 0) { return 0; }
    if (value % factor == 0) { return value / factor; }
    return value / factor + 1;
}

int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

// ------------------------------------------------------------------
// Output shape computation (matches PyTorch max_pool3d behavior)
// ------------------------------------------------------------------
void ComputeOutputShape(int64_t d, int64_t h, int64_t w,
                         int64_t kd, int64_t kh, int64_t kw,
                         int64_t sd, int64_t sh, int64_t sw,
                         int64_t pd, int64_t ph, int64_t pw,
                         bool ceil_mode,
                         int64_t &od, int64_t &oh, int64_t &ow)
{
    if (!ceil_mode) {
        od = (d + 2 * pd - kd) / sd + 1;
        oh = (h + 2 * ph - kh) / sh + 1;
        ow = (w + 2 * pw - kw) / sw + 1;
    } else {
        od = CeilDiv(d + 2 * pd - kd, sd) + 1;
        oh = CeilDiv(h + 2 * ph - kh, sh) + 1;
        ow = CeilDiv(w + 2 * pw - kw, sw) + 1;
        // C++ max_pool3d ceil_mode: clip extraneous output
        if ((od - 1) * sd >= d + pd) { --od; }
        if ((oh - 1) * sh >= h + ph) { --oh; }
        if ((ow - 1) * sw >= w + pw) { --ow; }
    }
}

// ------------------------------------------------------------------
// Populate tiling struct
// ------------------------------------------------------------------
void PopulateTiling(MaxPool3dKernelTiling *tiling,
                     int32_t n, int32_t c, int32_t d, int32_t h, int32_t w,
                     int32_t od, int32_t oh, int32_t ow,
                     int32_t kd, int32_t kh, int32_t kw,
                     int32_t sd, int32_t sh, int32_t sw,
                     int32_t pd, int32_t ph, int32_t pw,
                     int32_t vectorLen, int32_t launchBlocks)
{
    tiling->N = n;
    tiling->C = c;
    tiling->D = d;  tiling->H = h;  tiling->W = w;
    tiling->OD = od;  tiling->OH = oh;  tiling->OW = ow;
    tiling->kD = kd;  tiling->kH = kh;  tiling->kW = kw;
    tiling->sD = sd;  tiling->sH = sh;  tiling->sW = sw;
    tiling->pD = pd;  tiling->pH = ph;  tiling->pW = pw;
    tiling->inSpatial = d * h * w;
    tiling->outSpatial = od * oh * ow;
    tiling->hw = h * w;
    tiling->vectorLen = vectorLen;
    tiling->launchBlocks = launchBlocks;
    tiling->totalRows = n * od * oh * ow;
}

}  // namespace

// ==================================================================
// Main entry point
// ==================================================================
at::Tensor max_pool3d(
    const at::Tensor &self,
    at::IntArrayRef kernel_size,
    at::IntArrayRef stride,
    at::IntArrayRef padding,
    bool ceil_mode)
{
    TORCH_CHECK(self.dim() == 5, "max_pool3d: input must be 5D (N, C, D, H, W)");
    TORCH_CHECK(!kernel_size.empty(), "max_pool3d: kernel_size must not be empty");
    TORCH_CHECK(self.dtype() == at::kFloat || self.dtype() == at::kHalf ||
                self.dtype() == at::kBFloat16,
                "max_pool3d: only float32, float16, bfloat16 supported");

    // --- Extract dimensions ---
    int64_t n = self.size(0);
    int64_t c = self.size(1);
    int64_t d = self.size(2);
    int64_t h = self.size(3);
    int64_t w = self.size(4);

    // --- Normalize parameters ---
    int64_t kd = kernel_size[0];
    int64_t kh = kernel_size.size() >= 2 ? kernel_size[1] : kd;
    int64_t kw = kernel_size.size() >= 3 ? kernel_size[2] : kd;

    int64_t sd, sh, sw;
    if (stride.empty()) {
        sd = kd;  sh = kh;  sw = kw;
    } else {
        sd = stride[0];
        sh = stride.size() >= 2 ? stride[1] : sd;
        sw = stride.size() >= 3 ? stride[2] : sd;
    }

    int64_t pd = padding.empty() ? 0 : padding[0];
    int64_t ph = padding.size() >= 2 ? padding[1] : pd;
    int64_t pw = padding.size() >= 3 ? padding[2] : pd;

    TORCH_CHECK(sd != 0 && sh != 0 && sw != 0, "max_pool3d: stride must be non-zero");

    // --- Compute output shape ---
    int64_t od, oh, ow;
    ComputeOutputShape(d, h, w, kd, kh, kw, sd, sh, sw, pd, ph, pw, ceil_mode, od, oh, ow);

    // --- Layout transformation: NCDHW → NDHWC → flatten ---
    at::Tensor x_ndhwc = self.permute({0, 2, 3, 4, 1}).contiguous();
    at::Tensor x_flat = x_ndhwc.reshape({n * d * h * w, c});
    TORCH_CHECK(x_flat.is_contiguous(), "max_pool3d: input must be contiguous after reshape");

    // --- Output allocation ---
    at::Tensor y_flat = at::empty({n * od * oh * ow, c},
                                   at::device(at::kPrivateUse1).dtype(self.dtype()));

    // --- Tiling ---
    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = platform->GetCoreNumAiv();
    uint64_t ubSize;
    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int32_t totalRows = static_cast<int32_t>(n * od * oh * ow);
    int32_t launchBlocks = static_cast<int32_t>(std::min(coreNum, static_cast<int64_t>(totalRows)));
    if (launchBlocks <= 0) { launchBlocks = 1; }

    // Choose vectorLen based on dtype and C dimension
    int32_t c32 = static_cast<int32_t>(c);
    int32_t vectorLen = 256;
    if (vectorLen > c32) { vectorLen = c32; }

    // Prepare tiling tensor
    at::Tensor tilingCpu = at::empty({static_cast<int64_t>(sizeof(MaxPool3dKernelTiling))},
                                      at::device(at::kCPU).dtype(at::kByte));
    auto *tiling = reinterpret_cast<MaxPool3dKernelTiling *>(tilingCpu.data_ptr());
    PopulateTiling(tiling,
                    static_cast<int32_t>(n), static_cast<int32_t>(c),
                    static_cast<int32_t>(d), static_cast<int32_t>(h), static_cast<int32_t>(w),
                    static_cast<int32_t>(od), static_cast<int32_t>(oh), static_cast<int32_t>(ow),
                    static_cast<int32_t>(kd), static_cast<int32_t>(kh), static_cast<int32_t>(kw),
                    static_cast<int32_t>(sd), static_cast<int32_t>(sh), static_cast<int32_t>(sw),
                    static_cast<int32_t>(pd), static_cast<int32_t>(ph), static_cast<int32_t>(pw),
                    vectorLen, launchBlocks);

    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    uint32_t blockDim = static_cast<uint32_t>(launchBlocks);

    // --- Launch kernel ---
    if (self.dtype() == at::kFloat) {
        EXEC_KERNEL_CMD(max_pool3d_float, blockDim, x_flat, y_flat, tilingNpu);
    } else if (self.dtype() == at::kHalf) {
        EXEC_KERNEL_CMD(max_pool3d_half, blockDim, x_flat, y_flat, tilingNpu);
    } else {  // bfloat16
        EXEC_KERNEL_CMD(max_pool3d_bfloat16, blockDim, x_flat, y_flat, tilingNpu);
    }

    // --- Restore layout: flatten → NDHWC → NCDHW ---
    at::Tensor y_ndhwc = y_flat.reshape({n, od, oh, ow, c});
    at::Tensor y_ncdhw = y_ndhwc.permute({0, 4, 1, 2, 3}).contiguous();

    return y_ncdhw;
}

}  // namespace ascend_kernel
