"""AscendC implementation for MaxPool3d.

The AscendC kernel handles:
  - NCDHW -> NDHWC -> flatten spatial layout transformation internally
  - MaxPool3d computation on flattened (N*D*H*W, C) layout
  - Result restoration to NCDHW
"""

import sys
from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "max_pool3d_ext*")

# Dual-path loading: whl import first, fallback to direct .so loading
try:
    import max_pool3d_ext  # noqa: F401
except ImportError:
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


def _expand_to_3(param, default):
    """Expand a scalar or None to a (D, H, W) 3-tuple."""
    if param is None:
        return (default, default, default)
    if isinstance(param, int):
        return (param, param, param)
    if isinstance(param, (list, tuple)):
        if len(param) == 1:
            return (param[0], param[0], param[0])
        if len(param) == 2:
            return (param[0], param[1], param[1])
        return tuple(param[:3])
    return (param, param, param)


class ModelNew(nn.Module):
    """MaxPool3d using AscendC kernel.

    Internally calls torch.ops.npu.max_pool3d() which includes layout
    transformation, kernel execution, and result restoration.
    """

    def __init__(self):
        super().__init__()

    def forward(
        self,
        x: torch.Tensor,
        kernel_size,
        stride=None,
        padding: int = 0,
        dilation: int = 1,
        ceil_mode: bool = False,
        return_indices: bool = False,
    ):
        """Apply 3D max pooling using AscendC kernel.

        Args:
            x: Input tensor of shape (N, C, D, H, W).
            kernel_size: Size of the pooling window (int or triple).
            stride: Stride (int or triple). Defaults to kernel_size.
            padding: Implicit zero padding (int or triple).
            dilation: Spacing between kernel elements (must be 1).
            ceil_mode: Use ceil instead of floor for output shape.
            return_indices: Must be False (not supported).

        Returns:
            torch.Tensor of shape (N, C, outD, outH, outW).
        """
        # Input validation
        if x.ndim != 5:
            raise ValueError(
                f"Expected 5D input (N,C,D,H,W), got shape={tuple(x.shape)}"
            )
        if x.dtype not in (torch.float16, torch.float32, torch.bfloat16):
            raise ValueError(f"Unsupported dtype {x.dtype}")
        if dilation != 1:
            raise ValueError("dilation > 1 not supported by AscendC kernel")
        if return_indices:
            raise ValueError("return_indices not supported by AscendC kernel")

        # Expand parameters
        k = list(_expand_to_3(kernel_size, 1))
        if stride is None:
            stride = k
        s = list(_expand_to_3(stride, 1))
        p = list(_expand_to_3(padding, 0))

        # Call registered AscendC kernel
        return torch.ops.npu.max_pool3d(x, k, s, p, ceil_mode)
